def full_ids(prefixes):
    import sys
    data = json.load(open(sys.argv[1]))
    ids = [l["id"] for c in data for l in c["lessons"]]
    out = {}
    for p in prefixes:
        hit = [i for i in ids if i.startswith(p)]
        assert len(hit) == 1, p
        out[p] = hit[0]
    return out


if __name__ == "__main__":
    m = full_ids(list(L))
    items = [{"lesson_id": m[k], "questions": v} for k, v in L.items()]
    out = Path(__file__).resolve().parents[1] / "review-q-2111.json"
    out.write_text(json.dumps(items, ensure_ascii=False, indent=1), encoding="utf-8")
    print(out, sum(len(v) for v in L.values()))
